 #[test]fn all_fixed_families_use_their_own_actual_manual_allocator_and_reload_writer(){for(kind,n,bullet)in[("cannon",1,0),("missile",2,0),("gatling",0,1),("howitzer",1,0)]{let mut g=field(kind);manual(&mut g,101,15);let hp=g.units[1].hp;let slot=g.units[0].native_slot.unwrap();let w=g.units[0].native_hardware_slot.unwrap();let rng=g.original_rng.words;assert!(g.update_native_hardware_fire(0));assert_eq!((g.projectiles.len(),g.bullets.len()),(n,bullet),"{kind}");assert_eq!(g.units[0].native_reload7b,-1);assert_eq!(g.native_hardware_pool[w].order.target,[460,320]);assert_eq!(g.native_group_rosters.members[slot].as_ref().unwrap().flags69&32,0);assert_eq!(g.native_group_rosters.members[slot].as_ref().unwrap().promotion.timer3d,4);assert_eq!(g.units[1].hp,hp,"release is not contact");if kind!="gatling"{assert_eq!(g.original_rng.words,rng);for shot in g.native_hardware_shot_debug(){assert_eq!(shot.4,2);assert_eq!(shot.0,if kind=="howitzer"{Kind::Howitzer}else if kind=="missile"{Kind::Rocket}else{Kind::Shell});}}g.finish_native_unit_callback(0,Some(slot));assert_eq!((g.projectiles.len(),g.bullets.len()),(n,bullet),"no second footer shot");}}
 #[test]fn full_and_zero_speed_attempts_keep_reload_without_touching_an_old_last_shot(){for kind in["cannon","missile","gatling","howitzer"]{for full in[false,true]{let mut g=field(kind);manual(&mut g,80,if full{15}else{0});if full{if kind=="gatling"{let u=g.units[0].clone();for _ in 0..200{assert!(g.emit_native_bullet(&u,(100,100),(1200,1200),800,false,Attack{target:usize::MAX,damage:4,aim:50,facing:2,bullet:true}));}}else{fill_heavy(&mut g,50);}}let before=g.native_hardware_shot_debug();let bullets=g.bullets.len();assert!(g.update_native_hardware_fire(0));assert_eq!(g.units[0].native_reload7b,20,"{kind} full{full}");assert_eq!(g.native_hardware_shot_debug(),before);assert_eq!(g.bullets.len(),bullets);}}}
 #[test]fn a_partial_missile_salvo_updates_only_the_successful_returned_projectile(){let mut g=field("missile");manual(&mut g,80,15);fill_heavy(&mut g,49);assert!(g.update_native_hardware_fire(0));let shots=g.native_hardware_shot_debug();assert_eq!(shots.len(),50);assert!(shots[..49].iter().all(|p|p.4==1));assert_eq!(shots[49].4,2,"the failed second barrel must not increment the previous output pointer");assert_eq!(shots[49].0,Kind::Rocket);assert_eq!(g.units[0].native_reload7b,20);}
 #[test]fn a_live_45b050_target_releases_through_the_finite_hardware_caller(){let mut g=field("medium");let slot=g.units[0].native_slot.unwrap();let target=g.units[1].native_slot.unwrap();let w=g.units[0].native_hardware_slot.unwrap();let mut order=g.native_hardware_pool[w].order;order.target=[-4321,target as i16];g.native_hardware_pool[w].set_order(order);g.native_hardware_pool[w].attributes.bytes[21]=2;g.units[0].native_timer3c=0;g.units[0].native_reload7b=0;g.native_group_rosters.members[slot].as_mut().unwrap().flags69=128;g.native_group_rosters.current_roster.map(|r|{g.native_group_rosters.pool[r].roster[61]=0;g.native_group_rosters.pool[r].roster[58]=0;});assert!(g.update_native_hardware_fire(0));assert_eq!(g.projectiles.len(),1);assert_eq!(g.units[0].native_reload7b,30);assert_eq!(g.native_hardware_pool[w].order.target,[-4321,target as i16]);assert_eq!(g.native_hardware_shot_debug()[0].4,2);}
 #[test]fn all_fixed_target_callers_preserve_identity_and_read_the_live_unit_again(){for(kind,n,bullet)in[("cannon",1,0),("missile",2,0),("gatling",0,1),("howitzer",1,0)]{let mut g=field(kind);let slot=g.units[0].native_slot.unwrap();let other=g.units[1].native_slot.unwrap();let w=g.units[0].native_hardware_slot.unwrap();let mut order=g.native_hardware_pool[w].order;order.target=[-4321,other as i16];g.native_hardware_pool[w].set_order(order);g.units[0].angle=crate::native_math::angle(2);g.units[0].native_timer3c=0;g.units[0].native_reload7b=0;g.native_group_rosters.members[slot].as_mut().unwrap().flags31|=16;assert!(g.update_native_hardware_fire(0));assert_eq!((g.projectiles.len(),g.bullets.len()),(n,bullet),"{kind}");assert_eq!(g.native_hardware_pool[w].order.target,[-4321,other as i16]);let first=g.native_hardware_shot_debug().last().map(|p|p.2[0]);g.units[1].x+=80.;g.units[0].native_reload7b=0;g.units[0].native_timer3c=0;assert!(g.update_native_hardware_fire(0));assert_eq!((g.projectiles.len(),g.bullets.len()),(n*2,bullet*2));if let Some(first)=first{assert!(g.native_hardware_shot_debug().last().unwrap().2[0]>first);}assert_eq!(g.native_hardware_pool[w].order.target,[-4321,other as i16]);}}
